import React from 'react';
import { Link } from 'react-router-dom';
import '../styles/Paginas.css'; // Importamos los nuevos estilos

const Vision = () => {
  return (
    <div className="pagina-container">
      <div className="pagina-box">
        <img 
          src="https://res.cloudinary.com/diyd6flkf/image/upload/v1719443988/phg-solutions/logo-phg_n38v6b.png" 
          alt="Logo PHG Soluciones Contables" 
          className="pagina-logo" 
        />
        <h1>Nuestra Visión</h1>
        <p>
          Para el año 2030, aspiramos a ser una empresa líder en la prestación de servicios
          contables, reconocida por su calidad y compromiso con el desarrollo financiero de sus
          clientes en el departamento de Córdoba y el bajo cauca antioqueño, ofreciendo un
          acompañamiento continuo que garantice el éxito de quienes confían en nosotros.
        </p>
        <Link to="/" className="pagina-btn-volver">Volver al Inicio</Link>
      </div>
    </div>
  );
};

export default Vision;
